const edition = globalThis.makeSubjectEdition({"subject":"chip","year":2017,"grade":"3-4","contest":"Человек и природа","letters":"АБВГД","count":30,"language":"ru","points":3,"tasksFile":"задания_ЧИП-2017-3-4класс.pdf","answersFile":"reviewed-3-4.pdf","title":"Северная Америка","reviewedKey":true}, [{"title":"Что такое Северная Америка","question":"Что такое Северная Америка?","choices":["остров","полуостров","континент","мыс","гора"],"answer":2,"points":3,"steps":["Северная Америка — большая непрерывная область суши. К югу от неё лежит материк Южная Америка.","Такие крупные участки суши называют материками, или континентами."]},{"title":"Океан на пути Колумба","question":"Через какой океан экспедиция Колумба добралась из Европы до островов у берегов Америки?","choices":["Атлантический","Индийский","Северный Ледовитый","Тихий","Южный"],"answer":0,"points":3,"steps":["Экспедиция вышла из Испании и направилась на запад. На этом пути сначала были Канарские острова, затем Карибские.","Атлантический океан лежит между Европой и Америкой. Именно его пересекли корабли."],"figure":{"src":"assets/chip/2017/3-4-02.svg","alt":"На карте показаны Европа, запад Африки и обе Америки. Линии морского пути идут от юго-западной Европы к островам возле Америки.","width":400,"height":320,"detailSrc":"assets/chip/2017/3-4-02.svg"}},{"title":"Площадь стран материка","question":"Какая из стран Северной Америки самая большая по площади?","choices":["США","Куба","Мексика","Панама","Канада"],"answer":4,"points":3,"steps":["Канада занимает большую часть севера материка и множество арктических островов.","Площадь Канады близка к 10 млн км². Даже площадь США немного меньше."]},{"title":"Столица США","question":"Какой город является столицей США?","choices":["Вашингтон","Нью-Йорк","Чикаго","Филадельфия","Лос-Анджелес"],"answer":0,"points":3,"steps":["Столица США находится между штатами Мэриленд и Виргиния, в федеральном округе Колумбия.","Город называется Вашингтон. Там расположены Белый дом и Капитолий."]},{"title":"Транспорт в Диснейленде","question":"Какого из этих видов транспорта не было среди аттракционов Диснейленда в Калифорнии в год конкурса?","choices":["","","","",""],"answer":3,"points":3,"steps":["В парке есть небольшой поезд, монорельс, прогулочный пароход и старинные машины на Главной улице.","Под буквой Г — городской троллейбус, который получает электричество от проводов. Он к аттракционам парка не относился."],"adaptation":"Указано место и время, для которых перечислены аттракционы.","optionFigures":[{"src":"assets/chip/2017/3-4-05-1.webp","alt":"Паровоз и вагон на рельсах.","width":480,"height":340,"detailSrc":"assets/chip/2017/detail/3-4-05-1.webp","pixelWidth":138,"pixelHeight":133},{"src":"assets/chip/2017/3-4-05-2.webp","alt":"Поезд на приподнятом пути.","width":480,"height":360,"detailSrc":"assets/chip/2017/detail/3-4-05-2.webp","pixelWidth":138,"pixelHeight":133},{"src":"assets/chip/2017/3-4-05-3.webp","alt":"Белый многоярусный прогулочный пароход.","width":480,"height":444,"detailSrc":"assets/chip/2017/detail/3-4-05-3.webp","pixelWidth":138,"pixelHeight":133},{"src":"assets/chip/2017/3-4-05-4.webp","alt":"Городской пассажирский транспорт с контактными проводами.","width":480,"height":320,"detailSrc":"assets/chip/2017/detail/3-4-05-4.webp","pixelWidth":138,"pixelHeight":133},{"src":"assets/chip/2017/3-4-05-5.webp","alt":"Старинная двухэтажная машина с открытым верхом.","width":480,"height":360,"detailSrc":"assets/chip/2017/detail/3-4-05-5.webp","pixelWidth":480,"pixelHeight":360}]},{"title":"Зерно с полей США","question":"Какую из этих зерновых культур больше всего выращивали в США по массе урожая в год конкурса?","choices":["пшеница","рис","кукуруза","ячмень","рожь"],"answer":2,"points":3,"steps":["На Среднем Западе США находится большой сельскохозяйственный район, известный кукурузными полями.","Выращенную кукурузу употребляют в пищу, дают на корм животным и используют в промышленности. По массе урожая она опережала остальные указанные злаки."],"adaptation":"Указаны критерий сравнения и год выпуска."},{"title":"Кто унёс домик Элли","question":"Каким словом названо явление, которое унесло домик Элли в «Волшебнике Изумрудного города»?","choices":["метель","цунами","ураган","землетрясение","шторм"],"answer":2,"points":3,"steps":["Изображён сильный вращающийся вихрь. Он поднимает домик и несёт его далеко от Канзаса.","В сказке Александр Волков называет его ураганом. Слово в условии относится к книге."],"adaptation":"Спрашивается название явления в тексте сказки.","figure":{"src":"assets/chip/2017/3-4-07.svg","alt":"Сильный вихрь подхватил деревянный домик, и он накренился в воздухе.","width":640,"height":520,"detailSrc":"assets/chip/2017/3-4-07.svg","pixelWidth":640,"pixelHeight":520}},{"title":"Покров Гренландии","question":"Что покрывает большую часть Гренландии?","choices":["прерии","лёд","леса","озёра","тундра"],"answer":1,"points":3,"steps":["У побережья есть свободные ото льда участки. Большая часть внутренней территории покрыта толстым ледником.","Этот ледник называют Гренландским ледниковым щитом. Он удерживает огромные запасы пресной воды."]},{"title":"Электростанция на снимке","question":"На какой фотографии показана электростанция, которая использует энергию Солнца?","choices":["","","","",""],"answer":1,"points":3,"steps":["На солнечной тепловой станции множество зеркал может отражать лучи на вершину башни. Там свет нагревает теплоноситель.","Поле зеркал с башней видно на снимке Б. На других снимках используются ветер, вода или энергия топлива."],"optionFigures":[{"src":"assets/chip/2017/3-4-09-1.webp","alt":"Ряды высоких ветряков.","width":480,"height":320,"detailSrc":"assets/chip/2017/detail/3-4-09-1.webp","pixelWidth":138,"pixelHeight":132},{"src":"assets/chip/2017/3-4-09-2.webp","alt":"Ряды отражателей окружают высокую башню.","width":480,"height":360,"detailSrc":"assets/chip/2017/detail/3-4-09-2.webp","pixelWidth":1500,"pixelHeight":1124},{"src":"assets/chip/2017/3-4-09-3.webp","alt":"Плотина перегораживает большую реку.","width":480,"height":320,"detailSrc":"assets/chip/2017/detail/3-4-09-3.webp","pixelWidth":138,"pixelHeight":132},{"src":"assets/chip/2017/3-4-09-4.webp","alt":"Здания крупной промышленной станции.","width":480,"height":272,"detailSrc":"assets/chip/2017/detail/3-4-09-4.webp","pixelWidth":138,"pixelHeight":132},{"src":"assets/chip/2017/3-4-09-5.webp","alt":"Высокие трубы и градирни.","width":480,"height":306,"detailSrc":"assets/chip/2017/detail/3-4-09-5.webp","pixelWidth":138,"pixelHeight":132}]},{"title":"Самое высокое дерево","question":"К какому виду относится самое высокое из измеренных живых деревьев?","choices":["эвкалипт","калифорнийская сосна","сибирский кедр","секвойя вечнозелёная","пихта"],"answer":3,"points":3,"steps":["В прибрежных лесах Калифорнии растут деревья выше ста метров. Одно из самых высоких известных названо «Гиперион».","«Гиперион» — секвойя вечнозелёная. Её не следует путать с гигантским секвойядендроном, знаменитым толщиной ствола."]},{"title":"Герой сказок Римуса","question":"Какое животное — герой многих историй, которые рассказывает дядюшка Римус?","choices":["","","","",""],"answer":3,"points":4,"steps":["Дядюшка Римус рассказывает, как небольшой зверёк хитростью ускользает от более крупных противников, например от Братца Лиса.","Героя зовут Братец Кролик. Он изображён на снимке Г."],"adaptation":"Речь о герое рассказанных историй.","optionFigures":[{"src":"assets/chip/2017/3-4-11-1.webp","alt":"Рыже-чёрное насекомое с тонкими ногами.","width":480,"height":288,"detailSrc":"assets/chip/2017/detail/3-4-11-1.webp","pixelWidth":138,"pixelHeight":131},{"src":"assets/chip/2017/3-4-11-2.webp","alt":"Серебристая рыба с выступающими усами.","width":480,"height":311,"detailSrc":"assets/chip/2017/detail/3-4-11-2.webp","pixelWidth":138,"pixelHeight":131},{"src":"assets/chip/2017/3-4-11-3.webp","alt":"Крупная птица в полёте.","width":480,"height":320,"detailSrc":"assets/chip/2017/detail/3-4-11-3.webp","pixelWidth":480,"pixelHeight":320},{"src":"assets/chip/2017/3-4-11-4.webp","alt":"Небольшой зверёк с длинными ушами.","width":441,"height":480,"detailSrc":"assets/chip/2017/detail/3-4-11-4.webp","pixelWidth":138,"pixelHeight":131},{"src":"assets/chip/2017/3-4-11-5.webp","alt":"Белое животное с густой шерстью.","width":480,"height":321,"detailSrc":"assets/chip/2017/detail/3-4-11-5.webp","pixelWidth":480,"pixelHeight":321}]},{"title":"Собаки для упряжек","question":"Каких собак из этого списка обычно используют в ездовых упряжках?","choices":["далматинов","хаски","водолазов","эрдельтерьеров","догов"],"answer":1,"points":4,"steps":["Для упряжки важны выносливость и способность работать на морозе. У ездовых собак обычно густая шерсть.","Хаски относятся к ездовым собакам. Они способны долго тянуть лёгкую упряжку по снегу."]},{"title":"Дикобраз на снимке","question":"На каком снимке изображён североамериканский дикобраз?","choices":["","","","",""],"answer":1,"points":4,"steps":["Дикобраз выглядит крупнее ежа, у него негустая шерсть с длинными иглами и цепкие лапы. Он может забираться на деревья.","На рисунке Б видно такого зверя на ветке. На рисунке А — ёж с более круглым телом и короткими иглами."],"optionFigures":[{"src":"assets/chip/2017/3-4-13-1.webp","alt":"Небольшой зверёк с короткими иглами и вытянутой мордой.","width":480,"height":320,"detailSrc":"assets/chip/2017/detail/3-4-13-1.webp","pixelWidth":480,"pixelHeight":320},{"src":"assets/chip/2017/3-4-13-2.webp","alt":"Зверёк с длинными иглами на ветке.","width":480,"height":320,"detailSrc":"assets/chip/2017/detail/3-4-13-2.webp","pixelWidth":138,"pixelHeight":132},{"src":"assets/chip/2017/3-4-13-3.webp","alt":"Серый зверь с чёрно-белым рисунком головы.","width":480,"height":320,"detailSrc":"assets/chip/2017/detail/3-4-13-3.webp","pixelWidth":138,"pixelHeight":132},{"src":"assets/chip/2017/3-4-13-4.webp","alt":"Коренастый тёмный зверь со светло-бурой полосой по боку.","width":480,"height":300,"detailSrc":"assets/chip/2017/detail/3-4-13-4.webp","pixelWidth":138,"pixelHeight":132},{"src":"assets/chip/2017/3-4-13-5.webp","alt":"Серый зверёк держится за ствол дерева.","width":480,"height":472,"detailSrc":"assets/chip/2017/detail/3-4-13-5.webp","pixelWidth":138,"pixelHeight":132}]},{"title":"Волокна хлопчатника","question":"Какую часть хлопчатника собирают, чтобы получить хлопковое волокно?","choices":["стебель","листья","корень","цветки","коробочка"],"answer":4,"points":4,"steps":["Плод хлопчатника созревает и раскрывается. Внутри видны семена, окружённые длинными светлыми волосками.","Эти волоски отделяют и делают из них нити. Собирают раскрытые плоды-коробочки."]},{"title":"Первый национальный парк","question":"Какой парк стал первым национальным парком США?","choices":["Йеллоустонский","Йосемитский","Роки-Маунтин","Маунт-Рейнир","Денали"],"answer":0,"points":4,"steps":["В 1872 году США выделили территорию с гейзерами и горячими источниками для охраны и посещения.","Это был Йеллоустонский национальный парк. Остальные перечисленные парки получили этот статус позднее."]},{"title":"Птица Северной Америки","question":"Какая из этих птиц обитает в дикой природе Северной Америки?","choices":["","","","",""],"answer":0,"points":4,"steps":["У птицы на рисунке А длинный тонкий клюв. Она может зависать перед цветком, быстро двигая крыльями.","Это колибри. Несколько видов колибри живут в Северной Америке. Остальные снимки показывают птиц из других частей света."],"optionFigures":[{"src":"assets/chip/2017/3-4-16-1.webp","alt":"Маленькая птица зависла в воздухе, расправив крылья.","width":438,"height":480,"detailSrc":"assets/chip/2017/detail/3-4-16-1.webp","pixelWidth":138,"pixelHeight":131},{"src":"assets/chip/2017/3-4-16-2.webp","alt":"Крупные длинноногие птицы на открытой местности.","width":480,"height":320,"detailSrc":"assets/chip/2017/detail/3-4-16-2.webp","pixelWidth":138,"pixelHeight":131},{"src":"assets/chip/2017/3-4-16-3.webp","alt":"Чёрно-белая птица с красно-оранжевым клювом.","width":360,"height":480,"detailSrc":"assets/chip/2017/detail/3-4-16-3.webp","pixelWidth":360,"pixelHeight":480},{"src":"assets/chip/2017/3-4-16-4.webp","alt":"Яркая птица с вытянутыми декоративными перьями.","width":262,"height":480,"detailSrc":"assets/chip/2017/detail/3-4-16-4.webp","pixelWidth":262,"pixelHeight":480},{"src":"assets/chip/2017/3-4-16-5.webp","alt":"Светло-бурая птица сидит на округлом глиняном гнезде.","width":480,"height":360,"detailSrc":"assets/chip/2017/detail/3-4-16-5.webp","pixelWidth":1280,"pixelHeight":960}]},{"title":"Быстрый зверь прерий","question":"Какой из этих североамериканских зверей способен быстрее всех бежать по открытой местности?","choices":["вилорог","лось","бизон","белохвостый олень","пума"],"answer":0,"points":4,"steps":["Вилорог — стройное копытное прерий. Его длинные ноги и выносливость помогают убежать от хищника.","На коротком отрезке он может разогнаться до нескольких десятков километров в час и обгоняет остальных животных в списке."]},{"title":"Школьники на картине","question":"Какой город посетил Норман Роквелл перед тем, как написать показанную картину «Русский школьный класс»?","choices":["Нью-Йорк","Арлингтон","Москва","Вашингтон","Миннеаполис"],"answer":2,"points":4,"steps":["Художник рисовал не американский класс. На стене в русской школе виден бюст, а дети сидят за рядами парт.","Роквелл наблюдал школьную жизнь во время поездки в Москву. Его картина изображает московских школьников."],"adaptation":"Указано название картины, по которой определяется место действия.","figure":{"src":"assets/chip/2017/3-4-18.webp","alt":"Школьники сидят за партами, в глубине класса виден бюст.","width":480,"height":193,"detailSrc":"assets/chip/2017/detail/3-4-18.webp","pixelWidth":1600,"pixelHeight":642}},{"title":"Самая длинная река","question":"Какая из речных систем Северной Америки самая длинная по основному руслу и самому длинному притоку?","choices":["Колорадо","Макензи","Юкон","Миссисипи с Миссури","Рио-Гранде"],"answer":3,"points":4,"steps":["Речную систему сравнивают по самому длинному пути воды от удалённого истока до моря.","У Миссисипи такой маршрут проходит по Миссури и более мелким верхним притокам. Длина системы превышает шесть тысяч километров."],"adaptation":"Уточнено, что измеряется полная речная система, а не только русло с одним названием."},{"title":"Мяч бейсболиста","question":"Какой из этих мячей используют в бейсболе?","choices":["","","","",""],"answer":1,"points":4,"steps":["Нужно найти небольшой светлый мяч. Его кожаные части соединены изогнутым швом, обычно красного цвета.","Мяч с этим швом изображён под буквой Б. Большой мяч с тёмными линиями предназначен для баскетбола."],"optionFigures":[{"src":"assets/chip/2017/1-2-10-1.svg","alt":"Овальный коричневый мяч с белой шнуровкой.","width":130,"height":112,"detailSrc":"assets/chip/2017/1-2-10-1.svg"},{"src":"assets/chip/2017/1-2-10-2.svg","alt":"Белый мяч с двумя красными швами.","width":130,"height":112,"detailSrc":"assets/chip/2017/1-2-10-2.svg"},{"src":"assets/chip/2017/1-2-10-3.svg","alt":"Чёрно-белый мяч с многоугольными вставками.","width":130,"height":112,"detailSrc":"assets/chip/2017/1-2-10-3.svg"},{"src":"assets/chip/2017/1-2-10-4.svg","alt":"Оранжевый мяч с тёмными разделительными линиями.","width":130,"height":112,"detailSrc":"assets/chip/2017/1-2-10-4.svg"},{"src":"assets/chip/2017/1-2-10-5.svg","alt":"Красный мяч без тёмных линий и швов.","width":130,"height":112,"detailSrc":"assets/chip/2017/1-2-10-5.svg"}]},{"title":"Металлы Кордильер","question":"Какой из этих металлов не относится к цветным?","choices":["свинец","железо","цинк","медь","алюминий"],"answer":1,"points":5,"steps":["В металлургии железо и сплавы на его основе выделяют в отдельную группу чёрных металлов.","Свинец, цинк, медь и алюминий относятся к цветным. Вариант Б — железо."]},{"title":"Кто чует запах издалека","question":"Какая группа птиц известна тем, что некоторые её виды находят пищу по запаху?","choices":["орлы","совы","грифы","пеликаны","индейки"],"answer":2,"points":5,"steps":["Для поиска пищи многие птицы полагаются прежде всего на зрение. Но американский гриф-индейка может обнаружить пищу даже там, где она скрыта под кронами.","У этой птицы хорошо развито обоняние. Из перечисленных групп подходит вариант с грифами."]},{"title":"Прозвище певчей птицы","question":"Почему североамериканского серого пересмешника иногда называют кошачьей птицей?","choices":["он легко приручается","он охотится на домашних кошек","форма его черепа напоминает кошачий","он хорошо видит в темноте","один из его криков похож на мяуканье"],"answer":4,"points":5,"steps":["Эта певчая птица издаёт разные звуки и может подражать голосам других животных.","Один характерный крик напоминает кошачье мяуканье. С ним связано английское название catbird."],"adaptation":"Уточнён вид. В исходном буклете на фотографии изображена другая птица.","figure":{"src":"assets/chip/2017/3-4-23.webp","alt":"Серо-пепельная птица с тёмной шапочкой и длинным хвостом.","width":480,"height":360,"detailSrc":"assets/chip/2017/detail/3-4-23.webp","pixelWidth":1600,"pixelHeight":1200}},{"title":"Окраска зимой и летом","question":"У кого из перечисленных животных обычно нет заметной сезонной смены окраски на более светлую зимнюю?","choices":["у тундровой куропатки","у северного оленя","у полярного зайца северных популяций","у обыкновенного бурого лемминга","у песца белой формы"],"answer":3,"points":5,"steps":["У куропатки и белой формы песца на зиму покров становится светлым. У северного оленя зимняя шерсть обычно светлее или серебристее летней.","Для бурых леммингов резкая зимняя смена окраски не характерна. Некоторые другие лемминги, например копытные, заметно белеют."],"adaptation":"Сравнивается заметная смена окраски в конкретных группах, а не обновление волос или перьев."},{"title":"Родня луговых собачек","question":"Кто из этих животных ближе всего к луговым собачкам по родству?","choices":["собаки и лисицы","зайцы и кролики","хомяки и хомячки","норки и хорьки","суслики и сурки"],"answer":4,"points":5,"steps":["Луговые собачки живут колониями и роют норы. По строению зубов и родству они относятся к грызунам.","Их относят к семейству беличьих, как сусликов и сурков. Зверьки называются собачками из-за звуков, похожих на лай."],"figure":{"src":"assets/chip/2017/3-4-25.webp","alt":"Бурый грызун высунул голову из норы.","width":480,"height":360,"detailSrc":"assets/chip/2017/detail/3-4-25.webp","pixelWidth":181,"pixelHeight":170}},{"title":"Провалы в тундре","question":"Из-за чего летом в областях многолетней мерзлоты могут появляться новые провалы грунта?","choices":["из-за деятельности грызунов","из-за таяния льда в грунте","из-за ветрового выноса верхнего слоя","из-за вытаптывания травы оленями","из-за подъёма уровня океана"],"answer":1,"points":5,"steps":["Когда в земле много льда, он занимает часть объёма грунта. При потеплении лёд может растаять.","Талая вода стекает, и поверхность оседает. Так появляются ямы и трещины в тундре."]},{"title":"Обувь из музея","question":"На каком рисунке показаны мокасины, традиционная обувь ряда коренных народов Северной Америки?","choices":["","","","",""],"answer":1,"points":5,"steps":["У мокасин обычно мягкий кожаный верх и мягкая подошва. На показанной паре есть декоративные детали.","Такая обувь представлена под буквой Б. Плетёное изделие Г и туфли В и Д сделаны по другим традициям."],"optionFigures":[{"src":"assets/chip/2017/3-4-27-1.svg","alt":"Низкая чёрная туфля со светлым краем.","width":600,"height":285,"detailSrc":"assets/chip/2017/3-4-27-1.svg","pixelWidth":600,"pixelHeight":285},{"src":"assets/chip/2017/3-4-27-2.svg","alt":"Мягкая коричневая обувь с узорной вставкой и бахромой.","width":600,"height":285,"detailSrc":"assets/chip/2017/3-4-27-2.svg","pixelWidth":600,"pixelHeight":285},{"src":"assets/chip/2017/3-4-27-3.svg","alt":"Тёмная туфля с длинной петлёй над носком.","width":600,"height":285,"detailSrc":"assets/chip/2017/3-4-27-3.svg","pixelWidth":600,"pixelHeight":285},{"src":"assets/chip/2017/3-4-27-4.svg","alt":"Низкая плетёная обувь из широких светлых полос.","width":600,"height":285,"detailSrc":"assets/chip/2017/3-4-27-4.svg","pixelWidth":600,"pixelHeight":285},{"src":"assets/chip/2017/3-4-27-5.svg","alt":"Коричневая туфля с красным помпоном на носке.","width":600,"height":285,"detailSrc":"assets/chip/2017/3-4-27-5.svg","pixelWidth":600,"pixelHeight":285}]},{"title":"Куда смотрит компас","question":"Почему на севере Канады стрелка обычного компаса может заметно отклоняться от направления к географическому Северному полюсу?","choices":["там везде есть магнитная аномалия","географический полюс находится на Канадском архипелаге","поле нарушено испытаниями оружия","магнитный и географический полюсы не совпадают","в приборе замерзает смазка"],"answer":3,"points":5,"steps":["Географический Северный полюс определяется осью вращения Земли. Стрелка же ориентируется по местному магнитному полю.","Ориентиры не совпадают, и магнитный полюс перемещается. Поэтому показание компаса может отличаться от направления на географический полюс."]},{"title":"Остров и королевство","question":"Какой остров Северной Америки сегодня входит в состав Королевства Дания как самоуправляемая территория?","choices":["Гренландия","Куба","Гаити","Ямайка","Аляска"],"answer":0,"points":5,"steps":["Остров находится у северо-восточных берегов Северной Америки. Он исторически был связан с Норвегией, затем с Данией.","Гренландия находится в Северной Америке и входит в Королевство Дания. Так объясняется её политическая связь с Европой."],"adaptation":"Различено географическое положение острова и его государственная принадлежность."},{"title":"Пирамида Кукулькана","question":"В какой современной стране находится храм-пирамида Кукулькана?","choices":["Никарагуа","Мексика","Коста-Рика","Ямайка","Панама"],"answer":1,"points":5,"steps":["Храм стоит в Чичен-Ице, одном из древних городов майя. Его видно издалека по широким лестницам и ступенчатым ярусам.","Чичен-Ица расположена на полуострове Юкатан, на территории Мексики."],"figure":{"src":"assets/chip/2017/3-4-30.webp","alt":"Ступенчатая каменная пирамида с широкой лестницей и храмом наверху.","width":480,"height":255,"detailSrc":"assets/chip/2017/detail/3-4-30.webp","pixelWidth":1600,"pixelHeight":851}}]);
edition.sources.readers = {"tasksUrl":"assets/chip/2017/задания_ЧИП-2017-3-4класс-reading.pdf"};
